local ServiceDescriptor = require(script.Parent.ServiceDescriptor)
local ServiceDescriptorResolver = require(script.Parent.ServiceDescriptorResolver)
local ServiceResolver = {}
ServiceResolver.__index = ServiceResolver

function ServiceResolver.new(descriptor: ServiceDescriptor, luaTypeProvider)
	local self = setmetatable({}, ServiceResolver)
	self._serviceType = descriptor.ServiceType
	self._defaultDescriptor = descriptor
	self._luaTypeProvider = luaTypeProvider
	return self
end

function ServiceResolver.newWithDescriptors(
	serviceType: string,
	genericType: string,
	descriptors: { ServiceDescriptor },
	luaTypeProvider
)
	local self = setmetatable({}, ServiceResolver)
	self.IsMultiple = descriptors ~= nil
	self._serviceType = serviceType
	self.GenericTypeIfMultiple = genericType
	self._descriptors = descriptors
	self._luaTypeProvider = luaTypeProvider
	return self
end

function ServiceResolver:Relove(serviceProvider, service, unsolved)
	if self.IsMultiple then
		local result = {}
		for k, v in self._descriptors do
			table.insert(
				result,
				ServiceDescriptorResolver.Resolve(
					serviceProvider,
					self.GenericTypeIfMultiple,
					v,
					unsolved,
					self._luaTypeProvider
				)
			)
		end
		return result
	end

	return ServiceDescriptorResolver.Resolve(
		serviceProvider,
		service,
		self._defaultDescriptor,
		unsolved,
		self._luaTypeProvider
	)
end

return ServiceResolver
